	@Test
	void statementLookupUsesItsOwnStoreWithoutReplacingSharedExternalScalar(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, true)) {
			try (SailConnection writer = fixture.target.getConnection()) {
				writer.begin();
				writer.addStatement(SUBJECT, PREDICATE, fixture.expected);
				writer.commit();
			}
			long targetId = fixture.targetValues().getId(fixture.expected);
			assertTrue(targetId != LmdbValue.UNKNOWN_ID);
			ValueConstant scalar = new ValueConstant(fixture.nativeValue);
			StatementPattern pattern = new StatementPattern(new Var("s"), Var.of("p", PREDICATE),
					Var.of("provided", fixture.nativeValue));
			Join query = new Join(new Extension(new SingletonSet(), new ExtensionElem(scalar, "copy")), pattern);
			new LmdbValueLookupOptimizer(fixture.targetValues()).optimize(query, null,
					EmptyBindingSet.getInstance());
			assertSame(fixture.nativeValue, scalar.getValue(),
					"a later native consumer must not replace the public scalar's earlier-store identity");
			assertSame(fixture.nativeValue, pattern.getObjectVar().getValue());
			LmdbValueVar specialized = assertInstanceOf(LmdbValueVar.class, pattern.getObjectVar());
			assertTrue(specialized.isLmdbValueResolved());
			LmdbValue privateValue = specialized.getLmdbValue();
			assertEquals(targetId, privateValue.getInternalIdentity().id());
			assertSame(fixture.targetValues(), privateValue.getInternalIdentity().revision().getValueStore(),
					"numeric ID coincidence across stores is not dictionary authority");
			assertEquals(fixture.expected, fixture.nativeValue,
					"an actual statement consumer may use the RDF value without changing its meaning");
		}
	}

