	@Test
	void retainedBindingPayloadUsesTheExistingDecisionBudgetWithoutDisablingSmallKeys() {
		long budget = 64 * 1024L;
		MapBindingSet large = binding(VF.createLiteral("Ā".repeat((int) budget)));
		// This non-Latin-1 spelling exceeds the budget before any key/object overhead is counted.
		assertTrue(2L * ((Literal) large.getValue("provided")).getLabel().length() > budget);
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, budget);
		try {
			LmdbPipelinePlanCache.Context context = context(large);
			AtomicInteger computations = new AtomicInteger();
			cache.getOrCompute(cacheQuery(), context, context::revision, () -> plannedCacheQuery(computations));
			var repeated = cache.getOrCompute(cacheQuery(), context, context::revision,
					() -> plannedCacheQuery(computations));
			assertFalse(repeated.cacheHit(), "a retained bound literal larger than the existing budget cannot fit");
			assertEquals(2, computations.get());
			assertEquals(0, cache.entryCount());
			assertEquals(0L, cache.retainedBytes());
		} finally {
			cache.close();
		}
		LmdbPipelinePlanCache small = new LmdbPipelinePlanCache(8, 1, budget);
		try {
			LmdbPipelinePlanCache.Context context = context(binding(VF.createLiteral("small")));
			AtomicInteger computations = new AtomicInteger();
			small.getOrCompute(cacheQuery(), context, context::revision, () -> plannedCacheQuery(computations));
			assertTrue(small.getOrCompute(cacheQuery(), context, context::revision,
					() -> plannedCacheQuery(computations)).cacheHit(), "ordinary small detached keys still reuse");
			assertEquals(1, computations.get());
			assertTrue(small.retainedBytes() > 0L);
			assertTrue(small.retainedBytes() <= budget);
		} finally {
			small.close();
		}
	}

