		private static void seed(Path directory, Value value) {
			LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
			try {
				store.init();
				try (SailConnection writer = store.getConnection()) {
					writer.begin();
					writer.addStatement(SUBJECT, PREDICATE, value);
					writer.commit();
				}
			} catch (RuntimeException | Error failure) {
				try {
					store.shutDown();
				} catch (RuntimeException | Error cleanup) {
					if (cleanup != failure) {
						failure.addSuppressed(cleanup);
					}
				}
				throw failure;
			}
			store.shutDown();
		}

		private ValueStore targetValues() {
			return (ValueStore) target.getBackingStore().getValueFactory();
		}

		@Override
		public void close() {
			Throwable failure = null;
			try {
				target.shutDown();
			} catch (RuntimeException | Error problem) {
				failure = problem;
			}
			try {
				source.shutDown();
			} catch (RuntimeException | Error problem) {
				if (failure == null) {
					failure = problem;
				} else if (failure != problem) {
					failure.addSuppressed(problem);
				}
			}
			if (failure instanceof RuntimeException runtime) {
				throw runtime;
			}
			if (failure instanceof Error error) {
				throw error;
			}
		}
